    dsa_ext_endogenous_debt_dynamics_2 = CoordinateReader('dsa_ext_endogenous_debt_dynamics_2', data.DSA_EXT_ENDOGENOUS_DEBT_DYNAMICS_2.required.bind(TIME_PERIOD=input3_old_debt_service), dsa_ext_endogenous_debt_dynamics_2_formula)
