    dsa_ext_contribution_from_nominal_interest_rate = CoordinateReader('dsa_ext_contribution_from_nominal_interest_rate', data.DSA_EXT_CONTRIBUTION_FROM_NOMINAL_INTEREST_RATE.required.bind(TIME_PERIOD=input3_old_debt_service), dsa_ext_contribution_from_nominal_interest_rate_formula)
