        return as_measure(xl_add(xl_div(xl_mul(xl_neg(xl_mul(xl_div(dsa_ext_gdp_deflator_in_us_dollar_terms_change_in_percent[scenario, time_period], 100), xl_add(1, xl_div(dsa_ext_real_gdp_growth_in_percent[scenario, time_period], 100)))), dsa_ext_external_debt_nominal_1[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)]), dsa_ext_denominator_1_g_g[scenario, time_period]), xl_div(xl_mul(xl_mul(xl_mul(dsa_ext_share_of_local_currency_denominated_external_debt_to_total_external_debt[scenario, axis_step(_ax_time_period, time_period, -1)], xl_div(xl_neg(dsa_ext_depreciation_of_nc_depreciation[scenario, time_period]), 100)), xl_add(1, xl_div(dsa_ext_effective_interest_rate_percent_4[scenario, time_period], 100))), dsa_ext_external_debt_nominal_1[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)]), dsa_ext_denominator_1_g_g[scenario, time_period])))

