        if indicator == 'Non-interest current account in percent of GDP' and variant == 'Historical average':
            return as_measure(xl_neg(xl_average(view(dsa_ext_non_interest_current_account_deficit, cols={'SCENARIO': (scenario,), 'TIME_PERIOD': span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[3], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12])}))))
        elif indicator == 'Real GDP growth (in percent)' and variant == 'Historical average':
            return as_measure(xl_average(view(dsa_ext_real_gdp_growth_in_percent, cols={'SCENARIO': (scenario,), 'TIME_PERIOD': span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[3], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12])})))
