@publish(data.DSA_EXT_ADDITIONAL_DEBT_SERVICE_STRESS.schema, cells=data.DSA_EXT_ADDITIONAL_DEBT_SERVICE_STRESS.cells)
def dsa_ext_additional_debt_service_stress(*, dsa_ext_debt_services_associated_with_new_external_borrowing: data.Series[float | str | None], pv_stress_bounds_total_debt_service_in_usd: data.Series[float | str | None], pv_stress_total_debt_service: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute `dsa_ext_additional_debt_service_stress` using authored coordinate identities."""
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'A1' and _p_time_period >= 1:
            return as_measure(pv_stress_total_debt_service['Key variables at historical average', time_period])
        elif scenario == 'B1' and _p_time_period >= 1:
            return as_measure(pv_stress_bounds_total_debt_service_in_usd['Bounds Test 1: Real GDP Growth Shock', time_period])
        elif scenario == 'B4' and _p_time_period >= 1:
            return as_measure(pv_stress_bounds_total_debt_service_in_usd['Bound Test 4: Other Flows Shock', time_period])
        elif scenario == 'B5' and _p_time_period >= 1:
            return as_measure(pv_stress_bounds_total_debt_service_in_usd['Bounds Test 5: Exchange Rate Shock', time_period])
        elif scenario == 'B6_mkt' and _p_time_period >= 1:
            return as_measure(xl_add(pv_stress_bounds_total_debt_service_in_usd['Bounds Test 6: Combined Shock for Market Access Countries', time_period], dsa_ext_debt_services_associated_with_new_external_borrowing[scenario, time_period]))
        elif scenario == 'B6_nonmkt' and _p_time_period >= 1:
            return as_measure(pv_stress_bounds_total_debt_service_in_usd['Bounds Test 6: Combined Shock for Non-Market Access Countries', time_period])
        elif scenario == 'C3' and _p_time_period >= 1:
            return as_measure(pv_stress_total_debt_service['Tailored Stress Test 3. Commodity Price shock -External', time_period])
        return as_measure(pv_stress_bounds_total_debt_service_in_usd['Bound Test 2: Exports Shock', time_period])

    return data.DSA_EXT_ADDITIONAL_DEBT_SERVICE_STRESS.collect(evaluate(formula, data.DSA_EXT_ADDITIONAL_DEBT_SERVICE_STRESS.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_EXT_ADDITIONAL_DEBT_SERVICE_STRESS.required.bind(TIME_PERIOD=input3_old_debt_service))

