@publish(data.DSA_EXT_REVENUE.schema, cells=data.DSA_EXT_REVENUE.cells)
def dsa_ext_revenue(*, dsa_ext_nominal_gdp_million_of_us_dollars: data.Series[float | str | None], dsa_ext_revenue_gdp_stress_stress: data.Series[float | str | None], dsa_ext_government_revenues_excluding_grants_in_percent_of_gdp: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute `dsa_ext_revenue` using authored coordinate identities."""
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'C3' and _p_time_period <= 6:
            return as_measure(xl_mul(xl_div(dsa_ext_revenue_gdp_stress_stress[scenario, time_period], 100), dsa_ext_nominal_gdp_million_of_us_dollars[scenario, time_period]))
        return as_measure(xl_mul(xl_div(dsa_ext_government_revenues_excluding_grants_in_percent_of_gdp['Baseline', time_period], 100), dsa_ext_nominal_gdp_million_of_us_dollars[scenario, time_period]))

    return data.DSA_EXT_REVENUE.collect(evaluate(formula, data.DSA_EXT_REVENUE.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_EXT_REVENUE.required.bind(TIME_PERIOD=input3_old_debt_service))

