def scan_dsa_pub_public_sector_debt_1(*, dsa_pub_of_which_external_debt: data.Series[float | str | None], dsa_pub_primary_deficit: data.Series[float | str | None], dsa_pub_contribution_from_real_exchange_rate_depreciation: data.Series[float | str | None], dsa_pub_denominator_1_g: data.Series[float | str | None], dsa_pub_other_identified_debt_creating_flows: data.Series[float | str | None], dsa_pub_residual: data.Series[float | str | None], dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], dsa_pub_real_gdp_growth_in_percent: data.Series[float | str | None], dsa_pub_average_real_interest_rate_on_external_debt_in_percent: data.Series[float | str | None], dsa_pub_inflation_rate_gdp_deflator_in_percent: data.Series[float | str | None], dsa_pub_total_public_external_debt: data.Series[float | str | None], dsa_pub_domestic_debt: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService, macro_debt_gdp_current_prices_u_s_dollars: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series[float | str | None], macro_debt_total_public_debt_outstanding_year_end: data.Series[float | str | None], pv_resfin_pub_assumptions_average_interest_rate_on_domestic_debt: data.Series[float | str | None]) -> ScanDsaPubPublicSectorDebt1Result:
    """Evaluate the recurrence group `dsa_pub_public_sector_debt_1`, `dsa_pub_change_in_public_sector_debt`, `dsa_pub_identified_debt_creating_flows`, `dsa_pub_automatic_debt_dynamics`, `dsa_pub_contribution_from_interest_rate_growth_differential`, `dsa_pub_of_which_contribution_from_average_real_interest_rate`, `dsa_pub_of_which_contribution_from_real_gdp_growth`, `dsa_pub_average_nominal_interest_rate_on_domestic_debt_in_percent`, `dsa_pub_average_real_interest_rate_in_percent`, `dsa_pub_average_real_interest_rate_on_domestic_debt_in_percent`, `dsa_pub_nominal_debt`, `dsa_pub_total_public_domestic_debt` and publish complete tensors."""
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def dsa_pub_public_sector_debt_1_formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 0:
            return as_measure((xl_div(xl_mul(100, macro_debt_total_public_debt_outstanding_year_end[time_period]), xl_mul(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period])) if xl_bool(xl_isnumber(lambda: xl_div(macro_debt_total_public_debt_outstanding_year_end[time_period], xl_mul(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period])))) else '.'))
        return as_measure(xl_add(dsa_pub_public_sector_debt_1[scenario, axis_step(_ax_time_period, time_period, -1)], dsa_pub_change_in_public_sector_debt[scenario, time_period]))

    dsa_pub_public_sector_debt_1 = CoordinateReader('dsa_pub_public_sector_debt_1', data.DSA_PUB_PUBLIC_SECTOR_DEBT_1.required.bind(TIME_PERIOD=input3_old_debt_service), dsa_pub_public_sector_debt_1_formula)
    def dsa_pub_change_in_public_sector_debt_formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_add(dsa_pub_identified_debt_creating_flows[scenario, time_period], dsa_pub_residual[scenario, time_period]))

    dsa_pub_change_in_public_sector_debt = CoordinateReader('dsa_pub_change_in_public_sector_debt', data.DSA_PUB_CHANGE_IN_PUBLIC_SECTOR_DEBT.required.bind(TIME_PERIOD=input3_old_debt_service), dsa_pub_change_in_public_sector_debt_formula)
