def scan_dsa_pub_exchange_rate_lc_per_us_dollar(*, dsa_pub_b5_depreciation_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, input3_old_debt_service: data.Input3OldDebtService, baseline_pub_exchange_rate_lc_per_us_dollar: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar: data.Series[float | str | None]) -> ScanDsaPubExchangeRateLcPerUsDollarResult:
    """Evaluate the recurrence group `dsa_pub_exchange_rate_lc_per_us_dollar`, `dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc` and publish complete tensors."""
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def dsa_pub_exchange_rate_lc_per_us_dollar_formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'B5' and _p_time_period >= 1:
            return as_measure(xl_div(1, dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc[scenario, time_period]))
        elif scenario == 'A1':
            return as_measure(macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period])
        return as_measure(baseline_pub_exchange_rate_lc_per_us_dollar[time_period])

    dsa_pub_exchange_rate_lc_per_us_dollar = CoordinateReader('dsa_pub_exchange_rate_lc_per_us_dollar', data.DSA_PUB_EXCHANGE_RATE_LC_PER_US_DOLLAR.required.bind(TIME_PERIOD=input3_old_debt_service), dsa_pub_exchange_rate_lc_per_us_dollar_formula)
    def dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc_formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 0:
            return as_measure(xl_div(1, dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        return as_measure(xl_mul(dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc[scenario, axis_step(_ax_time_period, time_period, -1)], xl_add(1, xl_div(dsa_pub_b5_depreciation_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent[scenario, time_period], 100))))

