    """Compute `dsa_pub_inflation_rate_gdp_deflator_in_percent` using authored coordinate identities."""
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'B6_mkt' and _p_time_period == 1:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_nominal_debt, dsa_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent[scenario, time_period])))
        elif scenario == 'B5' and _p_time_period == 1:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_mul(leftover_real_interest_rate[scenario], dsa_pub_b5_depreciation_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent[scenario, time_period])))
        elif scenario == 'B6_nonmkt' and _p_time_period == 1:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_mul(b6_combo_nonmkt_pub_in_billions_of_lc, dsa_pub_b6_combo_non_mkt_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent[scenario, time_period])))
        elif scenario == 'C3' and _p_time_period == 1:
            return as_measure(xl_mul(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_add(1, xl_div(xl_mul(dsa_pub_c3_commodity_prices_pub_decline_in_gdp_deflator, dsa_ext_exports[scenario, axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)]), 100))))
        elif scenario == 'C3' and _p_time_period == 2:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_div(xl_mul(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[15]], dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, _ax_time_period.keys[1]]), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 1)), c3_commodity_pub_historical_statistics_key_variables_past_10)))
        elif scenario == 'C3' and _p_time_period == 3:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_div(xl_mul(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[15]], dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, _ax_time_period.keys[1]]), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 2)), c3_commodity_pub_historical_statistics_key_variables_past_10)))
        elif scenario == 'C3' and _p_time_period == 4:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_div(xl_mul(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[15]], dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, _ax_time_period.keys[1]]), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 3)), c3_commodity_pub_historical_statistics_key_variables_past_10)))
        elif scenario == 'C3' and _p_time_period == 5:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_div(xl_mul(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[15]], dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, _ax_time_period.keys[1]]), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 4)), c3_commodity_pub_historical_statistics_key_variables_past_10)))
        elif scenario == 'C3' and _p_time_period == 6:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_div(xl_mul(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[15]], dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, _ax_time_period.keys[1]]), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 5)), c3_commodity_pub_historical_statistics_key_variables_past_10)))
        elif scenario == 'A1' and _p_time_period == 1:
            return as_measure(a1_hist_pub_historical_statistics['Inflation rate (GDP deflator, in percent)', 'Historical average'])
        elif scenario == 'B1' and _p_time_period <= 2:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_mul(xl_sub(baseline_pub_real_gdp_growth[time_period], dsa_pub_real_gdp_growth_in_percent[scenario, time_period]), leftover_real_interest_rate[scenario])))
        elif scenario == 'A1' and _p_time_period >= 2:
            return as_measure(dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, axis_step(_ax_time_period, time_period, -1)])
        return as_measure(baseline_pub_inflation_rate_gdp_deflator_pct[time_period])

    dsa_pub_inflation_rate_gdp_deflator_in_percent = CoordinateReader('dsa_pub_inflation_rate_gdp_deflator_in_percent', data.DSA_PUB_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT.required.bind(TIME_PERIOD=input3_old_debt_service), formula)
    return data.DSA_PUB_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT.collect(((coord, dsa_pub_inflation_rate_gdp_deflator_in_percent[coord]) for coord in data.DSA_PUB_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.DSA_PUB_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT.required.bind(TIME_PERIOD=input3_old_debt_service))

