@publish(data.DSA_PUB_INPUT2_COVERAGE.schema, cells=data.DSA_PUB_INPUT2_COVERAGE.cells)
def dsa_pub_input2_coverage(*, contingent_liability_financial_market_pct_gdp: float | str, in2_coverage_ppp: float | str, in2_coverage_other_elements_of_govt_not_captured_in_1: int | str, in2_coverage_soe_s_debt_guaranteed_not_guaranteed_government: int | str) -> data.Series[float | str | None]:
    """Compute `dsa_pub_input2_coverage` using authored coordinate identities."""
    def formula(scenario: str, indicator: str) -> float | str | None:
        if indicator == 'Other general government':
            return as_measure(in2_coverage_other_elements_of_govt_not_captured_in_1)
        elif indicator == 'SoEs':
            return as_measure(in2_coverage_soe_s_debt_guaranteed_not_guaranteed_government)
        elif indicator == 'PPP':
            return as_measure(in2_coverage_ppp)
        return as_measure(contingent_liability_financial_market_pct_gdp)

    return data.DSA_PUB_INPUT2_COVERAGE.collect(evaluate(formula, data.DSA_PUB_INPUT2_COVERAGE.required))

