    def ext_debt_new_disbursements_non_residents_formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Locally-issued debt held by non-residents' and time_period <= 2034:
            return as_measure(xl_add(ext_debt_new_disbursements_non_residents['Denominated in local currency (LC)', time_period], ext_debt_new_disbursements_non_residents['Denominated in foreign currency (FX)', time_period]))
        elif instrument == 'Denominated in local currency (LC)' and time_period <= 2034:
            return as_measure(xl_sum(view(ext_debt_new_disbursements_non_residents, rows=span(data.INSTRUMENT_AXIS_15, 'Bonds (1 to 3 years)-LC', 'Bonds (beyond 7 years)-LC'), cols=(time_period,))))
        elif instrument == 'Denominated in foreign currency (FX)' and time_period <= 2034:
            return as_measure(xl_sum(view(ext_debt_new_disbursements_non_residents, rows=span(data.INSTRUMENT_AXIS_15, 'Bonds (1 to 3 years)-FX', 'Bonds (beyond 7 years)-FX'), cols=(time_period,))))
        elif instrument in ('Bonds (1 to 3 years)-FX', 'Bonds (4 to 7 years)-FX', 'Bonds (beyond 7 years)-FX') and time_period >= 2045:
            return as_measure(xl_div(None, None))
        elif instrument in ('Bonds (1 to 3 years)-LC', 'Bonds (4 to 7 years)-LC', 'Bonds (beyond 7 years)-LC') and time_period <= 2044:
            return as_measure((xl_div(input5_new_issuance[instrument, 'non-residents', time_period], ext_debt_exchange_rate_period_average[time_period]) if xl_bool(xl_eq(ext_debt_definition_external_domestic, lookup_afg)) else 0))
        return as_measure(xl_div(input5_new_issuance[instrument, 'non-residents', time_period], ext_debt_exchange_rate_period_average[time_period]))

