    def ext_debt_new_disbursements_residents_formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Denominated in foreign currency (FX)' and time_period <= 2034:
            return as_measure(xl_sum(view(ext_debt_new_disbursements_residents, rows=span(data.INSTRUMENT_AXIS_16, 'Bonds (1 to 3 years)-FX', 'Bonds (beyond 7 years)-FX'), cols=(time_period,))))
        elif instrument in ('Bonds (1 to 3 years)-FX', 'Bonds (4 to 7 years)-FX', 'Bonds (beyond 7 years)-FX') and time_period >= 2045:
            return as_measure((0 if xl_bool(xl_eq(ext_debt_definition_external_domestic, lookup_afg)) else xl_div(None, None)))
        return as_measure((0 if xl_bool(xl_eq(ext_debt_definition_external_domestic, lookup_afg)) else xl_div(input5_new_issuance[instrument, 'residents', time_period], ext_debt_exchange_rate_period_average[time_period])))

