        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 0:
            return as_measure(input5_vintage_projection_years_principal[time_period], 'int')
        return as_measure(xl_add(input5_vintage_projection_years_interest[axis_step(_ax_time_period, time_period, -1)], 1), 'int')

