@publish(data.INPUT5_VINTAGE_INSTRUMENT_LABEL.schema, cells=data.INPUT5_VINTAGE_INSTRUMENT_LABEL.cells)
def input5_vintage_instrument_label(*, input5_instrument_titles: data.Series[str | int | float | bool | None]) -> data.Series[str | int | float | bool | None]:
    """Compute `input5_vintage_instrument_label` using authored coordinate identities."""
    def formula(instrument: str, holder: str, issuance_year: int) -> str | int | float | bool | None:
        if issuance_year == 2024:
            return as_measure(input5_instrument_titles[instrument], 'str')
        return as_measure(input5_vintage_instrument_label[instrument, holder, issuance_year - 1], 'str')

    input5_vintage_instrument_label = CoordinateReader('input5_vintage_instrument_label', data.INPUT5_VINTAGE_INSTRUMENT_LABEL.required, formula)
    return data.INPUT5_VINTAGE_INSTRUMENT_LABEL.collect((coord, input5_vintage_instrument_label[coord]) for coord in data.INPUT5_VINTAGE_INSTRUMENT_LABEL.required)

@publish(data.A1_HIST_PUB_HISTORICAL_STATISTICS.schema, cells=data.A1_HIST_PUB_HISTORICAL_STATISTICS.cells)
def a1_hist_pub_historical_statistics(*, baseline_pub_inflation_rate_gdp_deflator_pct_al: float | str, baseline_pub_primary_deficit_by_indicator: data.Series[float | str | None], baseline_pub_real_gdp_growth_by_indicator: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute `a1_hist_pub_historical_statistics` using authored coordinate identities."""
    def formula(indicator: str, variant: str) -> float | str | None:
        if indicator == 'Primary deficit':
            return as_measure(baseline_pub_primary_deficit_by_indicator['Historical'])
        elif indicator == 'Real GDP growth (in percent)':
            return as_measure(baseline_pub_real_gdp_growth_by_indicator['Historical'])
        return as_measure(baseline_pub_inflation_rate_gdp_deflator_pct_al)

    return data.A1_HIST_PUB_HISTORICAL_STATISTICS.collect(evaluate(formula, data.A1_HIST_PUB_HISTORICAL_STATISTICS.required))

@publish(key=(), domain=None, cells=data.BLEND_CALCULATED_BLEND_RATE_CELLS)
def blend_calculated_blend_rate(*, blend_ibrd_group_a_pricing: float | str, blend_sofr_selected_by_maturity: float | str) -> float | str:
    """Compute `blend_calculated_blend_rate` using authored coordinate identities."""
    try:
        return as_measure(xl_sub(xl_add(blend_sofr_selected_by_maturity, blend_ibrd_group_a_pricing), xl_div(2.5, 100)))
    except XlError as error:
        return error.code

