@publish(data.CHART_PROJECTION_YEARS.schema, cells=data.CHART_PROJECTION_YEARS.cells)
def chart_projection_years(*, macro_debt_main_assumptions_further_details: int | str, macro_debt_further_details: data.Series[int | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[int | str | None]:
    """Compute `chart_projection_years` using authored coordinate identities."""
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> int | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 0:
            return as_measure(macro_debt_main_assumptions_further_details, 'int')
        return as_measure(macro_debt_further_details[time_period], 'int')

    return data.CHART_PROJECTION_YEARS.collect(evaluate(formula, data.CHART_PROJECTION_YEARS.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.CHART_PROJECTION_YEARS.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.CHART_INTERNAL_CHART_DATA_PV_OF_DEBT_TO_GDP_RATIO_PV_DEBT_TO_GDP_STRESS_PATH.schema, cells=data.CHART_INTERNAL_CHART_DATA_PV_OF_DEBT_TO_GDP_RATIO_PV_DEBT_TO_GDP_STRESS_PATH.cells)
def chart_internal_chart_data_pv_of_debt_to_gdp_ratio_pv_debt_to_gdp_stress_path(*, dsa_pub_pv_of_total_public_debt: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute `chart_internal_chart_data_pv_of_debt_to_gdp_ratio_pv_debt_to_gdp_stress_path` using authored coordinate identities."""
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'B2.1 Primary balance Market':
            return as_measure(dsa_pub_pv_of_total_public_debt['B2_mkt', time_period])
        elif scenario == 'B2.2 Primary balance Non-Market':
            return as_measure(dsa_pub_pv_of_total_public_debt['B2_nonmkt', time_period])
        elif scenario == 'B6.1 Combination of B1-B5 Market':
            return as_measure(dsa_pub_pv_of_total_public_debt['B6_mkt', time_period])
        return as_measure(dsa_pub_pv_of_total_public_debt['B6_nonmkt', time_period])

    return data.CHART_INTERNAL_CHART_DATA_PV_OF_DEBT_TO_GDP_RATIO_PV_DEBT_TO_GDP_STRESS_PATH.collect(evaluate(formula, data.CHART_INTERNAL_CHART_DATA_PV_OF_DEBT_TO_GDP_RATIO_PV_DEBT_TO_GDP_STRESS_PATH.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.CHART_INTERNAL_CHART_DATA_PV_OF_DEBT_TO_GDP_RATIO_PV_DEBT_TO_GDP_STRESS_PATH.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.CHART_INTERNAL_CHART_DATA_PV_OF_DEBT_TO_REVENUE_RATIO_PV_DEBT_TO_REVENUE.schema, cells=data.CHART_INTERNAL_CHART_DATA_PV_OF_DEBT_TO_REVENUE_RATIO_PV_DEBT_TO_REVENUE.cells)
def chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue(*, chart_output_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue: data.ChartOutputChartDataPvOfDebtToRevenueRatioPvDebtToRevenue, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute `chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue` using authored coordinate identities."""
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, variant: str) -> float | str | None:
        if scenario == 'B1. Real GDP growth' and variant == '1st year breach - 2024':
            return as_measure(xl_rank(chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue[scenario, 'Number of breaches exc. 1st year - 2024'], (chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue[scenario, 'Number of breaches exc. 1st year - 2024'], chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue['B2. Primary balance', 'Number of breaches exc. 1st year - 2024'], chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue['B3. Exports', 'Number of breaches exc. 1st year - 2024'], chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue['B4. Other flows 3/', 'Number of breaches exc. 1st year - 2024'], chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue['B5. Depreciation', 'Number of breaches exc. 1st year - 2024'], chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue['B6. Combination of B1-B5', 'Number of breaches exc. 1st year - 2024'], chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue['C1. Combined contingent liabilities', 'Number of breaches exc. 1st year - 2024'], chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue['C2. Natural disaster', 'Number of breaches exc. 1st year - 2024'], chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue['C3. Commodity price', 'Number of breaches exc. 1st year - 2024'], chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue['C4. Market Financing', 'Number of breaches exc. 1st year - 2024']), 0))
        elif scenario == 'C4. Market Financing' and variant == '1st year breach - 2024':
            return as_measure(xl_rank(chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue[scenario, 'Number of breaches exc. 1st year - 2024'], (chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue['B1. Real GDP growth', 'Number of breaches exc. 1st year - 2024'], chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue['B2. Primary balance', 'Number of breaches exc. 1st year - 2024'], chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue['B3. Exports', 'Number of breaches exc. 1st year - 2024'], chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue['B4. Other flows 3/', 'Number of breaches exc. 1st year - 2024'], chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue['B5. Depreciation', 'Number of breaches exc. 1st year - 2024'], chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue['B6. Combination of B1-B5', 'Number of breaches exc. 1st year - 2024'], chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue['C1. Combined contingent liabilities', 'Number of breaches exc. 1st year - 2024'], chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue['C2. Natural disaster', 'Number of breaches exc. 1st year - 2024'], chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue['C3. Commodity price', 'Number of breaches exc. 1st year - 2024'], chart_internal_chart_data_pv_of_debt_to_revenue_ratio_pv_debt_to_revenue[scenario, 'Number of breaches exc. 1st year - 2024']), 0))
