@publish(data.EXT_DEBT_OLD_MLT_DEBT_SERVICE.schema, cells=data.EXT_DEBT_OLD_MLT_DEBT_SERVICE.cells)
def ext_debt_old_mlt_debt_service(*, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute `ext_debt_old_mlt_debt_service` using authored coordinate identities."""
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Multilaterals' and time_period <= 2044:
            return as_measure(xl_sum(view(ext_debt_old_mlt_debt_service, rows=('IMF', 'IDA - regular', 'IDA - 50Y loans', 'IDA - SML', 'MULTI1', 'MULTI2'), cols=(time_period,))))
        elif instrument == 'Other Multilaterals' and time_period <= 2044:
            return as_measure(xl_sum(view(ext_debt_old_mlt_debt_service, rows=span(data.INSTRUMENT_AXIS, 'OTH_MULTI1', 'OTH_MULTI3'), cols=(time_period,))))
        elif instrument == 'Official Bilaterals' and time_period <= 2044:
            return as_measure(xl_add(ext_debt_old_mlt_debt_service['Paris Club', time_period], ext_debt_old_mlt_debt_service['Non-Paris Club', time_period]))
        elif instrument == 'Paris Club' and time_period <= 2044:
            return as_measure(xl_sum(view(ext_debt_old_mlt_debt_service, rows=span(data.INSTRUMENT_AXIS, 'Export Credit Agencies', 'PC5'), cols=(time_period,))))
        elif instrument == 'Non-Paris Club' and time_period <= 2044:
            return as_measure(xl_sum(view(ext_debt_old_mlt_debt_service, rows=span(data.INSTRUMENT_AXIS, 'Export Import Bank of NPC', 'NPC5'), cols=(time_period,))))
        elif instrument == 'Commercial' and time_period <= 2044:
            return as_measure(xl_sum(view(ext_debt_old_mlt_debt_service, rows=span(data.INSTRUMENT_AXIS, 'Eurobond', 'COM5'), cols=(time_period,))))
        elif instrument == 'IMF':
            return as_measure((input3_old_debt_service[instrument, time_period] if xl_bool(xl_isnumber(lambda: input3_old_debt_service[instrument, time_period])) else 0))
        elif instrument == 'IDA - regular':
            return as_measure((input3_old_debt_service['IDA (OLD_IDA1)', time_period] if xl_bool(xl_isnumber(lambda: input3_old_debt_service['IDA (OLD_IDA1)', time_period])) else 0))
        elif instrument == 'IDA - 50Y loans':
            return as_measure((input3_old_debt_service['IDA (OLD_IDA2)', time_period] if xl_bool(xl_isnumber(lambda: input3_old_debt_service['IDA (OLD_IDA2)', time_period])) else 0))
        elif instrument == 'IDA - SML':
            return as_measure((input3_old_debt_service['Multilateral1', time_period] if xl_bool(xl_isnumber(lambda: input3_old_debt_service['Multilateral1', time_period])) else 0))
        elif instrument == 'MULTI1':
            return as_measure((input3_old_debt_service['Multilateral2', time_period] if xl_bool(xl_isnumber(lambda: input3_old_debt_service['Multilateral2', time_period])) else 0))
        elif instrument == 'MULTI2':
            return as_measure((input3_old_debt_service['Multilateral3', time_period] if xl_bool(xl_isnumber(lambda: input3_old_debt_service['Multilateral3', time_period])) else 0))
        elif instrument == 'OTH_MULTI1':
            return as_measure((input3_old_debt_service['Other Multilateral1', time_period] if xl_bool(xl_isnumber(lambda: input3_old_debt_service['Other Multilateral1', time_period])) else 0))
        elif instrument == 'OTH_MULTI2':
            return as_measure((input3_old_debt_service['Other Multilateral2', time_period] if xl_bool(xl_isnumber(lambda: input3_old_debt_service['Other Multilateral2', time_period])) else 0))
        elif instrument == 'OTH_MULTI3':
            return as_measure((input3_old_debt_service['Other Multilateral3', time_period] if xl_bool(xl_isnumber(lambda: input3_old_debt_service['Other Multilateral3', time_period])) else 0))
        elif instrument == 'Export Credit Agencies':
            return as_measure((input3_old_debt_service['Paris Club1', time_period] if xl_bool(xl_isnumber(lambda: input3_old_debt_service['Paris Club1', time_period])) else 0))
        elif instrument == 'PC2':
            return as_measure((input3_old_debt_service['Paris Club2', time_period] if xl_bool(xl_isnumber(lambda: input3_old_debt_service['Paris Club2', time_period])) else 0))
        elif instrument == 'PC3':
            return as_measure((input3_old_debt_service['Paris Club3', time_period] if xl_bool(xl_isnumber(lambda: input3_old_debt_service['Paris Club3', time_period])) else 0))
        elif instrument == 'PC4':
            return as_measure((input3_old_debt_service['Paris Club4', time_period] if xl_bool(xl_isnumber(lambda: input3_old_debt_service['Paris Club4', time_period])) else 0))
        elif instrument == 'PC5':
            return as_measure((input3_old_debt_service['Paris Club5', time_period] if xl_bool(xl_isnumber(lambda: input3_old_debt_service['Paris Club5', time_period])) else 0))
        elif instrument == 'Export Import Bank of NPC':
            return as_measure((input3_old_debt_service['Non-Paris Club1', time_period] if xl_bool(xl_isnumber(lambda: input3_old_debt_service['Non-Paris Club1', time_period])) else 0))
        elif instrument == 'NPC2':
            return as_measure((input3_old_debt_service['Non-Paris Club2', time_period] if xl_bool(xl_isnumber(lambda: input3_old_debt_service['Non-Paris Club2', time_period])) else 0))
        elif instrument == 'NPC3':
            return as_measure((input3_old_debt_service['Non-Paris Club3', time_period] if xl_bool(xl_isnumber(lambda: input3_old_debt_service['Non-Paris Club3', time_period])) else 0))
        elif instrument == 'NPC4':
            return as_measure((input3_old_debt_service['Non-Paris Club4', time_period] if xl_bool(xl_isnumber(lambda: input3_old_debt_service['Non-Paris Club4', time_period])) else 0))
        elif instrument == 'NPC5':
            return as_measure((input3_old_debt_service['Non-Paris Club5', time_period] if xl_bool(xl_isnumber(lambda: input3_old_debt_service['Non-Paris Club5', time_period])) else 0))
        elif instrument == 'Eurobond':
            return as_measure((input3_old_debt_service['Commercial1', time_period] if xl_bool(xl_isnumber(lambda: input3_old_debt_service['Commercial1', time_period])) else 0))
        elif instrument == 'Commecial Bank':
            return as_measure((input3_old_debt_service['Commercial2', time_period] if xl_bool(xl_isnumber(lambda: input3_old_debt_service['Commercial2', time_period])) else 0))
        elif instrument == 'COM3':
            return as_measure((input3_old_debt_service['Commercial3', time_period] if xl_bool(xl_isnumber(lambda: input3_old_debt_service['Commercial3', time_period])) else 0))
        elif instrument == 'COM4':
            return as_measure((input3_old_debt_service['Commercial4', time_period] if xl_bool(xl_isnumber(lambda: input3_old_debt_service['Commercial4', time_period])) else 0))
        return as_measure((input3_old_debt_service['Commercial5', time_period] if xl_bool(xl_isnumber(lambda: input3_old_debt_service['Commercial5', time_period])) else 0))

    ext_debt_old_mlt_debt_service = CoordinateReader('ext_debt_old_mlt_debt_service', data.EXT_DEBT_OLD_MLT_DEBT_SERVICE.required, formula)
    return data.EXT_DEBT_OLD_MLT_DEBT_SERVICE.collect((coord, ext_debt_old_mlt_debt_service[coord]) for coord in data.EXT_DEBT_OLD_MLT_DEBT_SERVICE.required)

