@publish(data.IMPORTED_CLASSIFICATION_IDS.schema, cells=data.IMPORTED_CLASSIFICATION_IDS.cells)
def imported_classification_ids(*, imported_series_stub_cpia: str, imported_series_stub_gr_a: str, imported_series_stub_res_a: str, imported_series_stub_wgr: str, imported_components: data.Series[int | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[str | int | float | bool | None]:
    """Compute `imported_classification_ids` using authored coordinate identities."""
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(indicator: str, time_period: int) -> str | int | float | bool | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if indicator == 'CPIA':
            return as_measure(xl_concat(imported_series_stub_cpia, imported_components[time_period]), 'str')
        elif indicator == 'Real growth rate \n(in percent)':
            return as_measure(xl_concat(imported_series_stub_gr_a, imported_components[time_period]), 'str')
        elif indicator == 'Import coverage of reserves\n(in percent)':
            return as_measure(xl_concat(imported_series_stub_res_a, imported_components[time_period]), 'str')
        return as_measure(xl_concat(imported_series_stub_wgr, imported_components[time_period]), 'str')

