    realism1_external_year_headers = CoordinateReader('realism1_external_year_headers', data.REALISM1_EXTERNAL_YEAR_HEADERS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account), formula)
    return data.REALISM1_EXTERNAL_YEAR_HEADERS.collect(((coord, realism1_external_year_headers[coord]) for coord in data.REALISM1_EXTERNAL_YEAR_HEADERS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.REALISM1_EXTERNAL_YEAR_HEADERS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

