@publish(data.REALISM1_EXTERNAL_FIVE_YEAR_FLOW_CHANGES.schema, cells=data.REALISM1_EXTERNAL_FIVE_YEAR_FLOW_CHANGES.cells)
def realism1_external_five_year_flow_changes(*, realism1_external_five_years_ago_rebased_projection: data.Series[float | str | None], realism1_external_private_debt_rebased_change: data.Series[float | str | None], realism1_external_debt_creating_flows: data.Realism1ExternalDebtCreatingFlows, input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute `realism1_external_five_year_flow_changes` using authored coordinate identities."""
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    _realism1_external_five_year_flow_changes_table_0 = view(realism1_external_five_years_ago_rebased_projection, rows=('Contribution from nominal interest rate (in percent of GDP)',), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[8], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]))
    _realism1_external_five_year_flow_changes_table_1 = view(realism1_external_five_years_ago_rebased_projection, rows=('of which: contribution from real GDP growth (in percent of GDP)',), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[8], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]))
    _realism1_external_five_year_flow_changes_table_2 = view(realism1_external_five_years_ago_rebased_projection, rows=('Contribution from price and exchange rate changes (in percent of GDP)',), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[8], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]))
    _realism1_external_five_year_flow_changes_table_3 = view(realism1_external_private_debt_rebased_change, cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[8], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]))
    def formula(indicator: str, variant: str) -> float | str | None:
        if indicator == 'Current account + FDI' and variant == '5-year projected change':
            return as_measure(xl_sum(view(realism1_external_five_years_ago_rebased_projection, rows=(indicator,), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[8], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]))))
        elif indicator == 'Nominal interest rate' and variant == '5-year projected change':
            return as_measure(xl_sum(_realism1_external_five_year_flow_changes_table_0))
        elif indicator == 'Real GDP growth' and variant == '5-year projected change':
            return as_measure(xl_sum(_realism1_external_five_year_flow_changes_table_1))
        elif indicator == 'Price and exchange rate' and variant == '5-year projected change':
            return as_measure(xl_sum(_realism1_external_five_year_flow_changes_table_2))
        elif indicator == 'Change in PPG debt 3/' and variant == '5-year projected change':
            return as_measure(xl_sub(realism1_external_five_years_ago_rebased_projection['External debt o/w public and publicly guaranteed (in percent of GDP)', input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]], realism1_external_five_years_ago_rebased_projection['External debt o/w public and publicly guaranteed (in percent of GDP)', input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[7]]))
        elif indicator == 'Residual' and variant == '5-year projected change':
            return as_measure(xl_sub(xl_sum(view(realism1_external_five_years_ago_rebased_projection, rows=(indicator,), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[8], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]))), xl_sum(_realism1_external_five_year_flow_changes_table_3)))
        elif variant == '5-year historical change':
            return as_measure(realism1_external_debt_creating_flows[indicator, variant])
        return as_measure(xl_sub(realism1_external_five_year_flow_changes[indicator, '5-year historical change'], realism1_external_five_year_flow_changes[indicator, '5-year projected change']))

    realism1_external_five_year_flow_changes = CoordinateReader('realism1_external_five_year_flow_changes', data.REALISM1_EXTERNAL_FIVE_YEAR_FLOW_CHANGES.required, formula)
    return data.REALISM1_EXTERNAL_FIVE_YEAR_FLOW_CHANGES.collect((coord, realism1_external_five_year_flow_changes[coord]) for coord in data.REALISM1_EXTERNAL_FIVE_YEAR_FLOW_CHANGES.required)

