@publish(data.REALISM1_PUBLIC_FIVE_YEAR_FLOW_CHANGES.schema, cells=data.REALISM1_PUBLIC_FIVE_YEAR_FLOW_CHANGES.cells)
def realism1_public_five_year_flow_changes(*, realism1_public_five_years_ago_rebased_projection: data.Series[float | str | None], realism1_public_debt_creating_flows: data.Realism1PublicDebtCreatingFlows, input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute `realism1_public_five_year_flow_changes` using authored coordinate identities."""
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    _realism1_public_five_year_flow_changes_table_0 = view(realism1_public_five_years_ago_rebased_projection, rows=('of which: contribution from average real interest rate (in percent of GDP)',), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[8], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]))
    _realism1_public_five_year_flow_changes_table_1 = view(realism1_public_five_years_ago_rebased_projection, rows=('of which: contribution from real GDP growth (in percent of GDP)',), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[8], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]))
    _realism1_public_five_year_flow_changes_table_2 = view(realism1_public_five_years_ago_rebased_projection, rows=('Contribution from real exchange rate depreciation (in percent of GDP)',), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[8], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]))
    _realism1_public_five_year_flow_changes_table_3 = view(realism1_public_five_years_ago_rebased_projection, rows=('Change in public sector debt (in percent of GDP)',), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[8], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]))
    _realism1_public_five_year_flow_changes_table_4 = view(realism1_public_five_years_ago_rebased_projection, rows=('Other identified debt-creating flows (in percent of GDP)',), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[8], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]))
    def formula(indicator: str, variant: str) -> float | str | None:
        if indicator == 'Primary deficit' and variant == '2023-2028':
            return as_measure(xl_sum(view(realism1_public_five_years_ago_rebased_projection, rows=(f'{indicator} (in percent of GDP)',), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[8], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]))))
        elif indicator == 'Real interest rate' and variant == '2023-2028':
            return as_measure(xl_sum(_realism1_public_five_year_flow_changes_table_0))
        elif indicator == 'Real GDP growth' and variant == '2023-2028':
            return as_measure(xl_sum(_realism1_public_five_year_flow_changes_table_1))
        elif indicator == 'Real Exchange rate depreciation' and variant == '2023-2028':
            return as_measure(xl_sum(_realism1_public_five_year_flow_changes_table_2))
        elif indicator == 'Change in debt' and variant == '2023-2028':
            return as_measure(xl_sum(_realism1_public_five_year_flow_changes_table_3))
        elif indicator == 'Other debt creating flows' and variant == '2023-2028':
            return as_measure(xl_sum(_realism1_public_five_year_flow_changes_table_4))
        elif indicator == 'Residual' and variant == '2023-2028':
            return as_measure(xl_sum(view(realism1_public_five_years_ago_rebased_projection, rows=(indicator,), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[8], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]))))
        elif variant == '2018-2023':
            return as_measure(realism1_public_debt_creating_flows[indicator, '5-year historical change'])
        return as_measure(xl_sub(realism1_public_five_year_flow_changes[indicator, '2018-2023'], realism1_public_five_year_flow_changes[indicator, '2023-2028']))

    realism1_public_five_year_flow_changes = CoordinateReader('realism1_public_five_year_flow_changes', data.REALISM1_PUBLIC_FIVE_YEAR_FLOW_CHANGES.required, formula)
    return data.REALISM1_PUBLIC_FIVE_YEAR_FLOW_CHANGES.collect((coord, realism1_public_five_year_flow_changes[coord]) for coord in data.REALISM1_PUBLIC_FIVE_YEAR_FLOW_CHANGES.required)

