@publish(data.REALISM2_GROWTH_SHOCK.schema, cells=data.REALISM2_GROWTH_SHOCK.cells)
def realism2_growth_shock(*, realism2_multiplier_values: data.Series[float | str | None], realism2_constant_persistence: data.Series[float | str | None], realism2_persistence_values: data.Series[float | str | None], realism2_constant_shock_year_index: data.Series[float | str | None], realism2_shock_year_index: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute `realism2_growth_shock` using authored coordinate identities."""
    data.REALISM2_MULTIPLIER_VALUES.schema.validate(realism2_multiplier_values)
    data.REALISM2_CONSTANT_PERSISTENCE.schema.validate(realism2_constant_persistence)
    data.REALISM2_CONSTANT_SHOCK_YEAR_INDEX.schema.bind(TIME_PERIOD=input3_old_debt_service).validate(realism2_constant_shock_year_index)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int, scenario: str) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 0 and scenario == 'Multiplier = 0.2':
            return as_measure(xl_mul(xl_neg(realism2_multiplier_values[scenario]), xl_pow(realism2_constant_persistence[scenario], realism2_constant_shock_year_index[time_period])))
        elif _p_time_period == 1 and scenario == 'Multiplier = 0.2':
            return as_measure(xl_mul(xl_neg(realism2_multiplier_values[scenario]), xl_pow(realism2_constant_persistence[scenario], realism2_shock_year_index[time_period])))
        elif _p_time_period == 0 and scenario in ('Multiplier = 0.4', 'Multiplier = 0.6', 'Multiplier = 0.8', 'Multiplier = 1'):
            return as_measure(xl_mul(xl_neg(realism2_multiplier_values[scenario]), xl_pow(realism2_persistence_values[scenario], realism2_constant_shock_year_index[time_period])))
        return as_measure(xl_mul(xl_neg(realism2_multiplier_values[scenario]), xl_pow(realism2_persistence_values[scenario], realism2_shock_year_index[time_period])))

    return data.REALISM2_GROWTH_SHOCK.collect(evaluate(formula, data.REALISM2_GROWTH_SHOCK.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.REALISM2_GROWTH_SHOCK.required.bind(TIME_PERIOD=input3_old_debt_service))

