@publish(data.REALISM3_CONTRIBUTION_YEARS.schema, cells=data.REALISM3_CONTRIBUTION_YEARS.cells)
def realism3_contribution_years(*, realism3_first_projection_year: int | str, input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[int | str | None]:
    """Compute `realism3_contribution_years` using authored coordinate identities."""
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(time_period: int) -> int | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 13:
            return as_measure(realism3_first_projection_year, 'int')
        elif _p_time_period >= 14:
            return as_measure(xl_add(realism3_contribution_years[axis_step(_ax_time_period, time_period, -1)], 1), 'int')
        return as_measure(xl_sub(realism3_contribution_years[axis_step(_ax_time_period, time_period, 1)], 1), 'int')

    realism3_contribution_years = CoordinateReader('realism3_contribution_years', data.REALISM3_CONTRIBUTION_YEARS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account), formula)
    return data.REALISM3_CONTRIBUTION_YEARS.collect(((coord, realism3_contribution_years[coord]) for coord in data.REALISM3_CONTRIBUTION_YEARS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.REALISM3_CONTRIBUTION_YEARS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.REALISM3_GROWTH_CONTRIBUTIONS.schema, cells=data.REALISM3_GROWTH_CONTRIBUTIONS.cells)
def realism3_growth_contributions(*, realism3_capital_growth_contribution: data.Series[float | str | None], realism3_growth_residual: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute `realism3_growth_contributions` using authored coordinate identities."""
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(indicator: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        INDICATOR_TO_REALISM3_CAPITAL_GROWTH_CONTRIBUTION_VARIANT = {'Contribution of government capital (G) - Prev. DSA': 'Previous', 'Contribution of government capital (G) - Curr. DSA': 'Current'}
        INDICATOR_TO_REALISM3_GROWTH_RESIDUAL_VARIANT = {'Contribution of other factors - Prev. DSA': 'Previous', 'Contribution of other factors - Curr. DSA': 'Current'}
        if indicator in ('Contribution of government capital (G) - Prev. DSA', 'Contribution of government capital (G) - Curr. DSA'):
            return as_measure((xl_mul(realism3_capital_growth_contribution[INDICATOR_TO_REALISM3_CAPITAL_GROWTH_CONTRIBUTION_VARIANT[indicator], time_period], 100) if xl_bool(xl_isnumber(lambda: xl_mul(realism3_capital_growth_contribution[INDICATOR_TO_REALISM3_CAPITAL_GROWTH_CONTRIBUTION_VARIANT[indicator], time_period], 100))) else ''))
        return as_measure((xl_mul(realism3_growth_residual[INDICATOR_TO_REALISM3_GROWTH_RESIDUAL_VARIANT[indicator], time_period], 100) if xl_bool(xl_isnumber(lambda: xl_mul(realism3_growth_residual[INDICATOR_TO_REALISM3_GROWTH_RESIDUAL_VARIANT[indicator], time_period], 100))) else ''))

    return data.REALISM3_GROWTH_CONTRIBUTIONS.collect(evaluate(formula, data.REALISM3_GROWTH_CONTRIBUTIONS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.REALISM3_GROWTH_CONTRIBUTIONS.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

