@publish(data.REALISM3_GOVERNMENT_CAPITAL_GROWTH.schema, cells=data.REALISM3_GOVERNMENT_CAPITAL_GROWTH.cells)
def realism3_government_capital_growth(*, realism3_government_capital_projected_by_vintage: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute `realism3_government_capital_growth` using authored coordinate identities."""
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(variant: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if variant == 'Current' and _p_time_period <= 12:
            return as_measure((xl_sub(xl_div(realism3_government_capital_projected_by_vintage['Current', time_period], realism3_government_capital_projected_by_vintage['Current', axis_step(_ax_time_period, time_period, -1)]), 1) if xl_bool(xl_eq(xl_count(view(realism3_government_capital_projected_by_vintage, rows=('Current',), cols=span(_ax_time_period, axis_step(_ax_time_period, time_period, -1), time_period))), 2)) else '..'))
        return as_measure((xl_sub(xl_div(realism3_government_capital_projected_by_vintage[variant, time_period], realism3_government_capital_projected_by_vintage[variant, axis_step(_ax_time_period, time_period, -1)]), 1) if xl_bool(xl_eq(xl_count(view(realism3_government_capital_projected_by_vintage, rows=(variant,), cols=span(_ax_time_period, axis_step(_ax_time_period, time_period, -1), time_period))), 2)) else '..'))

    return data.REALISM3_GOVERNMENT_CAPITAL_GROWTH.collect(evaluate(formula, data.REALISM3_GOVERNMENT_CAPITAL_GROWTH.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.REALISM3_GOVERNMENT_CAPITAL_GROWTH.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.REALISM3_CAPITAL_GROWTH_CONTRIBUTION.schema, cells=data.REALISM3_CAPITAL_GROWTH_CONTRIBUTION.cells)
def realism3_capital_growth_contribution(*, realism3_output_elasticity: float | str, realism3_government_capital_growth: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute `realism3_capital_growth_contribution` using authored coordinate identities."""
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(variant: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if variant == 'Current' and _p_time_period <= 12:
            return as_measure((xl_mul(realism3_government_capital_growth['Current', time_period], realism3_output_elasticity) if xl_bool(xl_eq(xl_isnumber(lambda: realism3_government_capital_growth['Current', time_period]), True)) else '..'))
        return as_measure((xl_mul(realism3_government_capital_growth[variant, time_period], realism3_output_elasticity) if xl_bool(xl_eq(xl_isnumber(lambda: realism3_government_capital_growth[variant, time_period]), True)) else '..'))

    return data.REALISM3_CAPITAL_GROWTH_CONTRIBUTION.collect(evaluate(formula, data.REALISM3_CAPITAL_GROWTH_CONTRIBUTION.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.REALISM3_CAPITAL_GROWTH_CONTRIBUTION.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

@publish(data.REALISM3_GROWTH_RESIDUAL.schema, cells=data.REALISM3_GROWTH_RESIDUAL.cells)
def realism3_growth_residual(*, realism3_real_growth_by_vintage: data.Series[float | str | None], realism3_capital_growth_contribution: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute `realism3_growth_residual` using authored coordinate identities."""
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(variant: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if variant == 'Current' and _p_time_period <= 12:
            return as_measure((xl_sub(xl_div(realism3_real_growth_by_vintage['Current', time_period], 100), realism3_capital_growth_contribution['Current', time_period]) if xl_bool(xl_eq(xl_count(realism3_capital_growth_contribution['Current', time_period], realism3_real_growth_by_vintage['Current', time_period]), 2)) else '..'))
        return as_measure((xl_sub(xl_div(realism3_real_growth_by_vintage[variant, time_period], 100), realism3_capital_growth_contribution[variant, time_period]) if xl_bool(xl_eq(xl_count(realism3_capital_growth_contribution[variant, time_period], realism3_real_growth_by_vintage[variant, time_period]), 2)) else '..'))

    return data.REALISM3_GROWTH_RESIDUAL.collect(evaluate(formula, data.REALISM3_GROWTH_RESIDUAL.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.REALISM3_GROWTH_RESIDUAL.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

