@publish(data.IN8_SDR_SDR_INTEREST.schema, cells=data.IN8_SDR_SDR_INTEREST.cells)
def in8_sdr_sdr_interest(*, in8_sdr_sdr_allocation_holdings_in_million_of_usd: data.Series[int | str | None], discount_rate: float | str, input8_sdr_interest_historical: data.Input8SdrInterestHistorical, input8_sdr_interest: data.Input8SdrInterest, input8_sdr_interest_rate: float | str, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[int | str | None]:
    """Compute `in8_sdr_sdr_interest` using authored coordinate identities."""
    data.INPUT8_SDR_INTEREST_HISTORICAL.schema.bind(TIME_PERIOD=input3_old_debt_service).validate(input8_sdr_interest_historical)
    data.INPUT8_SDR_INTEREST.schema.bind(TIME_PERIOD=input3_old_debt_service).validate(input8_sdr_interest)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(issuance_year: int, time_period: int) -> int | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if issuance_year == 2024 and _p_time_period == 1:
            return as_measure((xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[issuance_year], input8_sdr_interest_historical[time_period]) if xl_bool(xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -1)], 0)) else 0), 'int')
        elif issuance_year == 2024 and _p_time_period == 4:
            return as_measure((xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -4)], input8_sdr_interest_historical[time_period]) if xl_bool(xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -1)], 0)) else 0), 'int')
        elif issuance_year == 2024 and _p_time_period == 5:
            return as_measure((xl_add(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -5)], input8_sdr_interest_historical[time_period]), xl_div(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -5)], input8_sdr_interest_historical[time_period]), discount_rate)) if xl_bool(xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -5)], 0)) else 0), 'int')
        elif issuance_year == 2025 and _p_time_period == 5:
            return as_measure((xl_add(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -4)], input8_sdr_interest_historical[time_period]), xl_div(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -4)], input8_sdr_interest_historical[time_period]), discount_rate)) if xl_bool(xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -4)], 0)) else 0), 'int')
        elif issuance_year == 2026 and _p_time_period == 5:
            return as_measure((xl_add(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -3)], input8_sdr_interest_historical[time_period]), xl_div(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -3)], input8_sdr_interest_historical[time_period]), discount_rate)) if xl_bool(xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -3)], 0)) else 0), 'int')
        elif issuance_year == 2027 and _p_time_period == 5:
            return as_measure((xl_add(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -2)], input8_sdr_interest_historical[time_period]), xl_div(xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -2)], input8_sdr_interest_historical[time_period]), discount_rate)) if xl_bool(xl_gt(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -2)], 0)) else 0), 'int')
