@publish(data.C4_MKT_FIN_STRESSED_LENDING_TERMS.schema, cells=data.C4_MKT_FIN_STRESSED_LENDING_TERMS.cells)
def c4_mkt_fin_stressed_lending_terms(*, c4_market_instruments: data.Series[int | str | None], c4_mkt_fin_net_non_debt_creating_flows_fdi_gdp_ratio_by_row: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute `c4_mkt_fin_stressed_lending_terms` using authored coordinate identities."""
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(instrument: str, variant: str) -> float | str | None:
        if variant == 'Bullet (1) or Amort. (>1)':
            return as_measure((1 if xl_bool(xl_le(xl_sub(c4_market_instruments[instrument, input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[13]], c4_market_instruments[instrument, input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]]), 1)) else 0))
        elif variant == 'Maturity':
            return as_measure((c4_mkt_fin_net_non_debt_creating_flows_fdi_gdp_ratio_by_row['If original maturity is greater than 5 years, new maturity is'] if xl_bool(xl_gt(c4_market_instruments[instrument, input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[13]], 5)) else xl_mul(c4_mkt_fin_net_non_debt_creating_flows_fdi_gdp_ratio_by_row['If original maturity is less than 5 years, new maturity is shortened by'], c4_market_instruments[instrument, input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[13]])))
        elif variant == 'Grace':
            return as_measure((xl_sub(c4_mkt_fin_stressed_lending_terms[instrument, 'Maturity'], 1) if xl_bool(xl_eq(c4_mkt_fin_stressed_lending_terms[instrument, 'Bullet (1) or Amort. (>1)'], 1)) else xl_min(xl_mul(c4_mkt_fin_net_non_debt_creating_flows_fdi_gdp_ratio_by_row['Shortening of grace period, for 3 years: shortened by'], c4_mkt_fin_stressed_lending_terms[instrument, 'Maturity']), c4_market_instruments[instrument, input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]])))
        elif variant == 'Maturity\n(rounded)':
            return as_measure(xl_rounddown(c4_mkt_fin_stressed_lending_terms[instrument, 'Maturity'], 0))
        return as_measure(xl_rounddown(c4_mkt_fin_stressed_lending_terms[instrument, 'Grace'], 0))

    c4_mkt_fin_stressed_lending_terms = CoordinateReader('c4_mkt_fin_stressed_lending_terms', data.C4_MKT_FIN_STRESSED_LENDING_TERMS.required, formula)
    return data.C4_MKT_FIN_STRESSED_LENDING_TERMS.collect((coord, c4_mkt_fin_stressed_lending_terms[coord]) for coord in data.C4_MKT_FIN_STRESSED_LENDING_TERMS.required)

@publish(data.C4_MKT_FIN_AVERAGE_RESIDUAL_TERMS.schema, cells=data.C4_MKT_FIN_AVERAGE_RESIDUAL_TERMS.cells)
def c4_mkt_fin_average_residual_terms(*, c4_mkt_fin_stressed_lending_terms: data.Series[float | str | None], c4_mkt_fin_total_commercial_borrowing_total: float | str, c4_mkt_fin_new_borrowing_total: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute `c4_mkt_fin_average_residual_terms` using authored coordinate identities."""
    def formula(variant: str) -> float | str | None:
        VARIANT_TO_C4_MKT_FIN_AVERAGE_RESIDUAL_TERMS = {'Maturity\n(rounded)': 'Maturity', 'Grace\n(rounded)': 'Grace'}
        if variant in ('Maturity', 'Grace'):
            return as_measure((0 if xl_bool(xl_eq(c4_mkt_fin_total_commercial_borrowing_total, 0)) else xl_div(xl_add(xl_add(xl_add(xl_add(xl_mul(c4_mkt_fin_stressed_lending_terms['Eurobond', variant], c4_mkt_fin_new_borrowing_total['Eurobond']), xl_mul(c4_mkt_fin_stressed_lending_terms['Commecial Bank', variant], c4_mkt_fin_new_borrowing_total['Commecial Bank'])), xl_mul(c4_mkt_fin_stressed_lending_terms['COM3', variant], c4_mkt_fin_new_borrowing_total['COM3'])), xl_mul(c4_mkt_fin_stressed_lending_terms['COM4', variant], c4_mkt_fin_new_borrowing_total['COM4'])), xl_mul(c4_mkt_fin_stressed_lending_terms['COM5', variant], c4_mkt_fin_new_borrowing_total['COM5'])), c4_mkt_fin_total_commercial_borrowing_total)))
        return as_measure(xl_rounddown(c4_mkt_fin_average_residual_terms[VARIANT_TO_C4_MKT_FIN_AVERAGE_RESIDUAL_TERMS[variant]], 0))

    c4_mkt_fin_average_residual_terms = CoordinateReader('c4_mkt_fin_average_residual_terms', data.C4_MKT_FIN_AVERAGE_RESIDUAL_TERMS.required, formula)
    return data.C4_MKT_FIN_AVERAGE_RESIDUAL_TERMS.collect((coord, c4_mkt_fin_average_residual_terms[coord]) for coord in data.C4_MKT_FIN_AVERAGE_RESIDUAL_TERMS.required)

