@publish(data.CI_SUMMARY_INDEX_COMPONENTS.schema, cells=data.CI_SUMMARY_INDEX_COMPONENTS.cells)
def ci_summary_index_components(*, ci_probit_coefficients: data.Series[float | str | None], ci_summary_components_by_year: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute `ci_summary_index_components` using authored coordinate identities."""
    data.CI_PROBIT_COEFFICIENTS.schema.validate(ci_probit_coefficients)
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    _ci_summary_index_components_table_0 = view(ci_probit_coefficients, rows=('Governance',), cols=span(data.INDICATOR_AXIS, 'PV of debt to GDP', 'Debt service to exports'))
    _ci_summary_index_components_table_1 = view(ci_probit_coefficients, rows=('Growth',), cols=span(data.INDICATOR_AXIS, 'PV of debt to GDP', 'Debt service to exports'))
    _ci_summary_index_components_table_2 = view(ci_summary_components_by_year, rows=('Real growth rate \n(in percent)',), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[8], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[17]))
    _ci_summary_index_components_table_3 = view(ci_probit_coefficients, rows=('Reserves',), cols=span(data.INDICATOR_AXIS, 'PV of debt to GDP', 'Debt service to exports'))
    _ci_summary_index_components_table_4 = view(ci_summary_components_by_year, rows=('Import coverage of reserves\n(in percent)',), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[8], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[17]))
    _ci_summary_index_components_table_5 = view(ci_probit_coefficients, rows=('Reserves^2',), cols=span(data.INDICATOR_AXIS, 'PV of debt to GDP', 'Debt service to exports'))
    _ci_summary_index_components_table_6 = view(ci_probit_coefficients, rows=('FX INCOME3',), cols=span(data.INDICATOR_AXIS, 'PV of debt to GDP', 'Debt service to exports'))
    _ci_summary_index_components_table_7 = view(ci_summary_components_by_year, rows=('Remittances\n(in percent)',), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[8], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[17]))
    _ci_summary_index_components_table_8 = view(ci_probit_coefficients, rows=('World Growth',), cols=span(data.INDICATOR_AXIS, 'PV of debt to GDP', 'Debt service to exports'))
    _ci_summary_index_components_table_9 = view(ci_summary_components_by_year, rows=('World economic growth \n(in percent)',), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[8], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[17]))
    def formula(indicator: str, variant: str) -> float | str | None:
        if indicator == 'CPIA' and variant == 'Coefficients (A)':
            return as_measure(xl_round(xl_neg(xl_average(_ci_summary_index_components_table_0)), 3))
        elif indicator == 'CPIA' and variant == '10-year average values (B)':
            return as_measure(xl_average(view(ci_summary_components_by_year, rows=(indicator,), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[8], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[17]))))
        elif indicator == 'CPIA' and variant == 'CI Score components \n(A*B) = (C)':
            return as_measure(xl_mul(ci_summary_index_components[indicator, 'Coefficients (A)'], ci_summary_index_components[indicator, '10-year average values (B)']))
        elif indicator == 'Real growth rate (in percent)' and variant == 'Coefficients (A)':
            return as_measure(xl_round(xl_neg(xl_average(_ci_summary_index_components_table_1)), 3))
        elif indicator == 'Real growth rate (in percent)' and variant == '10-year average values (B)':
            return as_measure(xl_average(_ci_summary_index_components_table_2))
        elif indicator == 'Import coverage of reserves (in percent)' and variant == 'Coefficients (A)':
            return as_measure(xl_round(xl_neg(xl_average(_ci_summary_index_components_table_3)), 3))
        elif indicator == 'Import coverage of reserves (in percent)' and variant == '10-year average values (B)':
            return as_measure(xl_average(_ci_summary_index_components_table_4))
        elif indicator == 'Import coverage of reserves^2  (in percent)' and variant == 'Coefficients (A)':
            return as_measure(xl_round(xl_neg(xl_average(_ci_summary_index_components_table_5)), 3))
        elif indicator == 'Import coverage of reserves^2  (in percent)' and variant == '10-year average values (B)':
            return as_measure(xl_div(xl_pow(xl_average(_ci_summary_index_components_table_4), 2), 100))
        elif indicator == 'Remittances (in percent)' and variant == 'Coefficients (A)':
            return as_measure(xl_round(xl_neg(xl_average(_ci_summary_index_components_table_6)), 3))
        elif indicator == 'Remittances (in percent)' and variant == '10-year average values (B)':
            return as_measure(xl_average(_ci_summary_index_components_table_7))
        elif indicator == 'World economic growth (in percent)' and variant == 'Coefficients (A)':
            return as_measure(xl_round(xl_neg(xl_average(_ci_summary_index_components_table_8)), 3))
        elif indicator == 'World economic growth (in percent)' and variant == '10-year average values (B)':
            return as_measure(xl_average(_ci_summary_index_components_table_9))
        return as_measure(xl_mul(xl_div(ci_summary_index_components[indicator, 'Coefficients (A)'], 100), ci_summary_index_components[indicator, '10-year average values (B)']))

    ci_summary_index_components = CoordinateReader('ci_summary_index_components', data.CI_SUMMARY_INDEX_COMPONENTS.required, formula)
    return data.CI_SUMMARY_INDEX_COMPONENTS.collect((coord, ci_summary_index_components[coord]) for coord in data.CI_SUMMARY_INDEX_COMPONENTS.required)

