@publish(data.CI_SUMMARY_COMPONENTS_BY_YEAR.schema, cells=data.CI_SUMMARY_COMPONENTS_BY_YEAR.cells)
def ci_summary_components_by_year(*, ci_remittances_higher_cutoff: float | str, imported_classification_values: data.Series[float | str | None], ci_summary_gdp_us_dollars_billions: data.Series[float | str | None], ci_summary_remittances_gross_us_dollars_billions: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute `ci_summary_components_by_year` using authored coordinate identities."""
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(indicator: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if indicator == 'Remittances\n(in percent)':
            return as_measure((ci_remittances_higher_cutoff if xl_bool(xl_gt(xl_mul(xl_div(ci_summary_remittances_gross_us_dollars_billions[time_period], ci_summary_gdp_us_dollars_billions[time_period]), 100), ci_remittances_higher_cutoff)) else xl_mul(xl_div(ci_summary_remittances_gross_us_dollars_billions[time_period], ci_summary_gdp_us_dollars_billions[time_period]), 100)))
        return as_measure(imported_classification_values[indicator, time_period])

    return data.CI_SUMMARY_COMPONENTS_BY_YEAR.collect(evaluate(formula, data.CI_SUMMARY_COMPONENTS_BY_YEAR.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.CI_SUMMARY_COMPONENTS_BY_YEAR.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

