@publish(data.CUSTOM_PUB_PLEASE_DO_NOT_CHANGE_THESE_NUMBERS.schema, cells=data.CUSTOM_PUB_PLEASE_DO_NOT_CHANGE_THESE_NUMBERS.cells)
def custom_pub_please_do_not_change_these_numbers(*, customized_public_template_anchor: float | str, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[int | str | None]:
    """Compute `custom_pub_please_do_not_change_these_numbers` using authored coordinate identities."""
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> int | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 1:
            return as_measure(xl_add(customized_public_template_anchor, 1), 'int')
        return as_measure(xl_add(custom_pub_please_do_not_change_these_numbers[axis_step(_ax_time_period, time_period, -1)], 1), 'int')

    custom_pub_please_do_not_change_these_numbers = CoordinateReader('custom_pub_please_do_not_change_these_numbers', data.CUSTOM_PUB_PLEASE_DO_NOT_CHANGE_THESE_NUMBERS.required.bind(TIME_PERIOD=input3_old_debt_service), formula)
    return data.CUSTOM_PUB_PLEASE_DO_NOT_CHANGE_THESE_NUMBERS.collect(((coord, custom_pub_please_do_not_change_these_numbers[coord]) for coord in data.CUSTOM_PUB_PLEASE_DO_NOT_CHANGE_THESE_NUMBERS.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.CUSTOM_PUB_PLEASE_DO_NOT_CHANGE_THESE_NUMBERS.required.bind(TIME_PERIOD=input3_old_debt_service))

