@dataclass(frozen=True, slots=True)
class ScanCustomExtExportsUsdResult:
    """Complete named results of one recurrence group evaluation."""
    custom_ext_exports_usd: data.Series[float | str | None]
    custom_ext_exports_growth: data.Series[float | str | None]
    custom_ext_exports_usd_stress: data.Series[float | str | None]
    custom_ext_exports_in_of_gdp_stress: data.Series[float | str | None]
    custom_ext_exports_by_year: data.Series[float | str | None]

def scan_custom_ext_exports_usd(*, dsa_ext_exports: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount, customized_public_template_anchor: float | str, customized_public_natural_disaster_year: int | str, input3_old_debt_service: data.Input3OldDebtService, custom_pub_please_do_not_change_these_numbers: data.Series[int | str | None], custom_ext_nominal_gdp_million_of_us_dollars: data.Series[float | str | None], custom_ext_nominal_gdp_million_of_us_dollars_by_year: data.Series[float | str | None], custom_ext_exports: data.Series[float | str | None], customized_scenario_spec: data.Series[float | str | None], custom_ext_ii_key_macroeconomic_nominal_gdp_million_of_us_dollars: float | str) -> ScanCustomExtExportsUsdResult:
    """Evaluate the recurrence group `custom_ext_exports_usd`, `custom_ext_exports_growth`, `custom_ext_exports_usd_stress`, `custom_ext_exports_in_of_gdp_stress`, `custom_ext_exports_by_year` and publish complete tensors."""
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def custom_ext_exports_usd_formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 12:
            return as_measure(xl_mul(xl_div(custom_ext_exports_by_year[time_period], 100), custom_ext_ii_key_macroeconomic_nominal_gdp_million_of_us_dollars))
        return as_measure(xl_mul(xl_div(custom_ext_exports[time_period], 100), custom_ext_nominal_gdp_million_of_us_dollars_by_year[time_period]))

    custom_ext_exports_usd = CoordinateReader('custom_ext_exports_usd', data.CUSTOM_EXT_EXPORTS_USD.required.bind(TIME_PERIOD=input3_input_3_macro_current_account), custom_ext_exports_usd_formula)
    def custom_ext_exports_growth_formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 0:
            return as_measure(xl_sub(xl_mul(xl_sub(xl_div(custom_ext_exports_usd[time_period], custom_ext_exports_usd[axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)]), 1), 100), (customized_scenario_spec['size_of_associated_exports_growth_shock', input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[11]] if xl_bool(xl_eq(customized_public_template_anchor, customized_public_natural_disaster_year)) else 0)))
        return as_measure(xl_sub(xl_mul(xl_sub(xl_div(custom_ext_exports_usd[time_period], custom_ext_exports_usd[axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)]), 1), 100), (customized_scenario_spec['size_of_associated_exports_growth_shock', input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[11]] if xl_bool(xl_eq(custom_pub_please_do_not_change_these_numbers[time_period], customized_public_natural_disaster_year)) else 0)))

    custom_ext_exports_growth = CoordinateReader('custom_ext_exports_growth', data.CUSTOM_EXT_EXPORTS_GROWTH.required.bind(TIME_PERIOD=input3_old_debt_service), custom_ext_exports_growth_formula)
    def custom_ext_exports_usd_stress_formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 0:
            return as_measure(xl_mul(custom_ext_exports_usd[axis_step(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), time_period, -1)], xl_add(1, xl_div(custom_ext_exports_growth[time_period], 100))))
        return as_measure(xl_mul(custom_ext_exports_usd_stress[axis_step(_ax_time_period, time_period, -1)], xl_add(1, xl_div(custom_ext_exports_growth[time_period], 100))))

    custom_ext_exports_usd_stress = CoordinateReader('custom_ext_exports_usd_stress', data.CUSTOM_EXT_EXPORTS_USD_STRESS.required.bind(TIME_PERIOD=input3_old_debt_service), custom_ext_exports_usd_stress_formula)
    def custom_ext_exports_in_of_gdp_stress_formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure(xl_mul(xl_div(custom_ext_exports_usd_stress[time_period], custom_ext_nominal_gdp_million_of_us_dollars[time_period]), 100))

    custom_ext_exports_in_of_gdp_stress = CoordinateReader('custom_ext_exports_in_of_gdp_stress', data.CUSTOM_EXT_EXPORTS_IN_OF_GDP_STRESS.required.bind(TIME_PERIOD=input3_old_debt_service), custom_ext_exports_in_of_gdp_stress_formula)
    def custom_ext_exports_by_year_formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 12:
            return as_measure(dsa_ext_exports['Baseline', time_period])
        return as_measure(custom_ext_exports_in_of_gdp_stress[time_period])

    custom_ext_exports_by_year = CoordinateReader('custom_ext_exports_by_year', data.CUSTOM_EXT_EXPORTS_BY_YEAR.required.bind(TIME_PERIOD=input3_input_3_macro_current_account), custom_ext_exports_by_year_formula)
    return ScanCustomExtExportsUsdResult(
        custom_ext_exports_usd=data.CUSTOM_EXT_EXPORTS_USD.collect(((coord, custom_ext_exports_usd[coord]) for coord in data.CUSTOM_EXT_EXPORTS_USD.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.CUSTOM_EXT_EXPORTS_USD.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)),
        custom_ext_exports_growth=data.CUSTOM_EXT_EXPORTS_GROWTH.collect(((coord, custom_ext_exports_growth[coord]) for coord in data.CUSTOM_EXT_EXPORTS_GROWTH.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.CUSTOM_EXT_EXPORTS_GROWTH.required.bind(TIME_PERIOD=input3_old_debt_service)),
        custom_ext_exports_usd_stress=data.CUSTOM_EXT_EXPORTS_USD_STRESS.collect(((coord, custom_ext_exports_usd_stress[coord]) for coord in data.CUSTOM_EXT_EXPORTS_USD_STRESS.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.CUSTOM_EXT_EXPORTS_USD_STRESS.required.bind(TIME_PERIOD=input3_old_debt_service)),
        custom_ext_exports_in_of_gdp_stress=data.CUSTOM_EXT_EXPORTS_IN_OF_GDP_STRESS.collect(((coord, custom_ext_exports_in_of_gdp_stress[coord]) for coord in data.CUSTOM_EXT_EXPORTS_IN_OF_GDP_STRESS.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.CUSTOM_EXT_EXPORTS_IN_OF_GDP_STRESS.required.bind(TIME_PERIOD=input3_old_debt_service)),
        custom_ext_exports_by_year=data.CUSTOM_EXT_EXPORTS_BY_YEAR.collect(((coord, custom_ext_exports_by_year[coord]) for coord in data.CUSTOM_EXT_EXPORTS_BY_YEAR.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.CUSTOM_EXT_EXPORTS_BY_YEAR.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)),
    )

