    return data.IN6OPT_STANDARD_NOMINAL_DEPRECIATION_CLOSE_REAL_OVERVALUATION.collect(evaluate(formula, data.IN6OPT_STANDARD_NOMINAL_DEPRECIATION_CLOSE_REAL_OVERVALUATION.required))

