@publish(data.IN8_SDR_SDR_ALLOCATION_HOLDINGS_IN_MILLION_OF_USD.schema, cells=data.IN8_SDR_SDR_ALLOCATION_HOLDINGS_IN_MILLION_OF_USD.cells)
def in8_sdr_sdr_allocation_holdings_in_million_of_usd(*, input8_sdr_stock: data.Input8SdrStock, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[int | str | None]:
    """Compute `in8_sdr_sdr_allocation_holdings_in_million_of_usd` using authored coordinate identities."""
    data.INPUT8_SDR_STOCK.schema.validate(input8_sdr_stock)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> int | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        return as_measure((0 if xl_bool(xl_lt(xl_sub(xl_sub(input8_sdr_stock[input8_sdr_stock.domain.axis('INDICATOR').keys[0]], xl_sum(())), xl_sub(input8_sdr_stock[input8_sdr_stock.domain.axis('INDICATOR').keys[1]], xl_sum(()))), 0)) else xl_sub(xl_sub(input8_sdr_stock[input8_sdr_stock.domain.axis('INDICATOR').keys[0]], xl_sum(())), xl_sub(input8_sdr_stock[input8_sdr_stock.domain.axis('INDICATOR').keys[1]], xl_sum(())))), 'int')

    return data.IN8_SDR_SDR_ALLOCATION_HOLDINGS_IN_MILLION_OF_USD.collect(evaluate(formula, data.IN8_SDR_SDR_ALLOCATION_HOLDINGS_IN_MILLION_OF_USD.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.IN8_SDR_SDR_ALLOCATION_HOLDINGS_IN_MILLION_OF_USD.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.IN8_SDR_INTEREST_PAYMENTS_IN_MILLION_OF_USD.schema, cells=data.IN8_SDR_INTEREST_PAYMENTS_IN_MILLION_OF_USD.cells)
def in8_sdr_interest_payments_in_million_of_usd(*, input8_sdr_interest_historical: data.Input8SdrInterestHistorical, input8_sdr_interest: data.Input8SdrInterest, input8_sdr_interest_rate: float | str, input8_sdr_stock: data.Input8SdrStock, in8_sdr_sdr_allocation_holdings_in_million_of_usd: data.Series[int | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[int | str | None]:
    """Compute `in8_sdr_interest_payments_in_million_of_usd` using authored coordinate identities."""
    data.INPUT8_SDR_INTEREST_HISTORICAL.schema.bind(TIME_PERIOD=input3_old_debt_service).validate(input8_sdr_interest_historical)
    data.INPUT8_SDR_INTEREST.schema.bind(TIME_PERIOD=input3_old_debt_service).validate(input8_sdr_interest)
    data.INPUT8_SDR_STOCK.schema.validate(input8_sdr_stock)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> int | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 0:
            return as_measure((xl_mul(xl_sub(input8_sdr_stock[input8_sdr_stock.domain.axis('INDICATOR').keys[0]], input8_sdr_stock[input8_sdr_stock.domain.axis('INDICATOR').keys[1]]), input8_sdr_interest_historical[time_period]) if xl_bool(xl_le(input8_sdr_stock[input8_sdr_stock.domain.axis('INDICATOR').keys[1]], input8_sdr_stock[input8_sdr_stock.domain.axis('INDICATOR').keys[0]])) else 0), 'int')
        elif _p_time_period == 20:
            return as_measure((xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -1)], input8_sdr_interest_rate) if xl_bool(xl_le(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -1)], input8_sdr_stock[input8_sdr_stock.domain.axis('INDICATOR').keys[0]])) else 0), 'int')
        elif 1 <= _p_time_period <= 5:
            return as_measure((xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -1)], input8_sdr_interest_historical[time_period]) if xl_bool(xl_le(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -1)], input8_sdr_stock[input8_sdr_stock.domain.axis('INDICATOR').keys[0]])) else 0), 'int')
        return as_measure((xl_mul(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -1)], input8_sdr_interest[time_period]) if xl_bool(xl_le(in8_sdr_sdr_allocation_holdings_in_million_of_usd[axis_step(_ax_time_period, time_period, -1)], input8_sdr_stock[input8_sdr_stock.domain.axis('INDICATOR').keys[0]])) else 0), 'int')

    return data.IN8_SDR_INTEREST_PAYMENTS_IN_MILLION_OF_USD.collect(evaluate(formula, data.IN8_SDR_INTEREST_PAYMENTS_IN_MILLION_OF_USD.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.IN8_SDR_INTEREST_PAYMENTS_IN_MILLION_OF_USD.required.bind(TIME_PERIOD=input3_old_debt_service))

@publish(data.IN8_SDR_PV_OF_INTEREST_PAYMENTS_IN_MILLION_OF_USD.schema, cells=data.IN8_SDR_PV_OF_INTEREST_PAYMENTS_IN_MILLION_OF_USD.cells)
def in8_sdr_pv_of_interest_payments_in_million_of_usd(*, discount_rate: float | str, in8_sdr_sdr_interest: data.Series[int | str | None], in8_sdr_of_end_2044: int | str, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[int | str | None]:
    """Compute `in8_sdr_pv_of_interest_payments_in_million_of_usd` using authored coordinate identities."""
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> int | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 0:
            return as_measure(xl_npv(discount_rate, view(in8_sdr_sdr_interest, rows=(time_period,), cols=span(_ax_time_period, axis_step(_ax_time_period, time_period, 1), axis_step(_ax_time_period, time_period, 5)))), 'int')
        elif _p_time_period == 1:
            return as_measure(xl_npv(discount_rate, view(in8_sdr_sdr_interest, rows=(time_period,), cols=span(_ax_time_period, axis_step(_ax_time_period, time_period, 1), axis_step(_ax_time_period, time_period, 4)))), 'int')
        elif _p_time_period == 2:
            return as_measure(xl_npv(discount_rate, view(in8_sdr_sdr_interest, rows=(time_period,), cols=span(_ax_time_period, axis_step(_ax_time_period, time_period, 1), axis_step(_ax_time_period, time_period, 3)))), 'int')
        elif _p_time_period == 3:
            return as_measure(xl_npv(discount_rate, view(in8_sdr_sdr_interest, rows=(time_period,), cols=span(_ax_time_period, axis_step(_ax_time_period, time_period, 1), axis_step(_ax_time_period, time_period, 2)))), 'int')
        elif _p_time_period == 20:
            return as_measure(xl_npv(discount_rate, (in8_sdr_of_end_2044,)), 'int')
        return as_measure(xl_npv(discount_rate, view(in8_sdr_sdr_interest, rows=(time_period,), cols=(axis_step(_ax_time_period, time_period, 1),))), 'int')

    return data.IN8_SDR_PV_OF_INTEREST_PAYMENTS_IN_MILLION_OF_USD.collect(evaluate(formula, data.IN8_SDR_PV_OF_INTEREST_PAYMENTS_IN_MILLION_OF_USD.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.IN8_SDR_PV_OF_INTEREST_PAYMENTS_IN_MILLION_OF_USD.required.bind(TIME_PERIOD=input3_old_debt_service))

