    return data.MACRO_DEBT_SHARE_OF_LOCAL_CURRENCY_DENOMINATED_EXTERNAL.collect(evaluate(formula, data.MACRO_DEBT_SHARE_OF_LOCAL_CURRENCY_DENOMINATED_EXTERNAL.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.MACRO_DEBT_SHARE_OF_LOCAL_CURRENCY_DENOMINATED_EXTERNAL.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

