@publish(data.MACRO_DEBT_PREVIOUS_VINTAGE_INVESTMENT.schema, cells=data.MACRO_DEBT_PREVIOUS_VINTAGE_INVESTMENT.cells)
def macro_debt_previous_vintage_investment(*, input3_investment: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Series[float | str | None]:
    """Compute `macro_debt_previous_vintage_investment` using authored coordinate identities."""
    data.INPUT3_INVESTMENT.schema.bind(TIME_PERIOD=input3_input_3_macro_current_account).validate(input3_investment)
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(indicator: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if indicator == 'Public Investment, constant prices' and _p_time_period <= 6:
            return as_measure((input3_investment['Public Investment, constant prices', time_period] if xl_bool(xl_isnumber(lambda: input3_investment['Public Investment, constant prices', time_period])) else 0))
        elif indicator == 'Public Investment in percent of GDP (real), previous DSA vintage' and _p_time_period <= 6:
            return as_measure((input3_investment['Public Investment in percent of GDP (real), previous DSA vintage', time_period] if xl_bool(xl_isnumber(lambda: input3_investment['Public Investment in percent of GDP (real), previous DSA vintage', time_period])) else 0))
        return as_measure((input3_investment[indicator, time_period] if xl_bool(xl_isnumber(lambda: input3_investment[indicator, time_period])) else 0))

    return data.MACRO_DEBT_PREVIOUS_VINTAGE_INVESTMENT.collect(evaluate(formula, data.MACRO_DEBT_PREVIOUS_VINTAGE_INVESTMENT.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.MACRO_DEBT_PREVIOUS_VINTAGE_INVESTMENT.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

