    data.INPUT3_NONRESIDENT_FOREIGN_CURRENCY_STOCK.schema.bind(TIME_PERIOD=input3_input_3_macro_current_account).validate(input3_nonresident_foreign_currency_stock)
    data.INPUT3_INPUT_3_MACRO_NATIONAL_CURRENCY_PER_U_S_DOLLAR_E_O_P.schema.bind(TIME_PERIOD=input3_input_3_macro_current_account).validate(input3_input_3_macro_national_currency_per_u_s_dollar_e_o_p)
    data.INPUT3_DOMESTIC_O_W_ST.schema.bind(TIME_PERIOD=input3_input_3_macro_current_account).validate(input3_domestic_o_w_st)
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    def formula(indicator: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_input_3_macro_current_account.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        INDICATOR_TO_INPUT3_NONRESIDENT_LOCAL_CURRENCY_STOCK = {'Outstanding': 'Outstanding of existing debt in local currency', 'o/w: short-term': 'o/w: short-term'}
        if indicator == 'o/w: short-term' and _p_time_period == 11:
            return as_measure((xl_add(xl_div((input3_nonresident_local_currency_stock[INDICATOR_TO_INPUT3_NONRESIDENT_LOCAL_CURRENCY_STOCK[indicator], time_period] if xl_bool(xl_isnumber(lambda: input3_nonresident_local_currency_stock[INDICATOR_TO_INPUT3_NONRESIDENT_LOCAL_CURRENCY_STOCK[indicator], time_period])) else 0), input3_input_3_macro_national_currency_per_u_s_dollar_e_o_p[time_period]), (input3_nonresident_foreign_currency_stock['o/w: short-term', time_period] if xl_bool(xl_isnumber(lambda: input3_nonresident_foreign_currency_stock['o/w: short-term', time_period])) else 0)) if xl_bool(xl_eq(external_domestic_debt_definition, lookup_afg)) else (input3_domestic_o_w_st['foreign', 'residents', time_period] if xl_bool(xl_isnumber(lambda: input3_domestic_o_w_st['foreign', 'residents', time_period])) else 0)))
        elif indicator == 'o/w: short-term' and _p_time_period <= 10:
            return as_measure((xl_add(xl_div((input3_nonresident_local_currency_stock[INDICATOR_TO_INPUT3_NONRESIDENT_LOCAL_CURRENCY_STOCK[indicator], time_period] if xl_bool(xl_isnumber(lambda: input3_nonresident_local_currency_stock[INDICATOR_TO_INPUT3_NONRESIDENT_LOCAL_CURRENCY_STOCK[indicator], time_period])) else 0), input3_input_3_macro_national_currency_per_u_s_dollar_e_o_p[time_period]), (input3_nonresident_foreign_currency_stock['o/w: short-term', time_period] if xl_bool(xl_isnumber(lambda: input3_nonresident_foreign_currency_stock['o/w: short-term', time_period])) else 0)) if xl_bool(xl_eq(external_domestic_debt_definition, lookup_afg)) else (input3_domestic_foreign_currency_stock['o/w: short-term', time_period] if xl_bool(xl_isnumber(lambda: input3_domestic_foreign_currency_stock['o/w: short-term', time_period])) else 0)))
        elif indicator == 'Foreign currency-denominated debt (including locally-issued debt)' and _p_time_period >= 7:
            return as_measure(xl_add(xl_add(xl_add((input3_ppg_external_debt_stock['PPG MLT external debt outstanding', time_period] if xl_bool(xl_isnumber(lambda: input3_ppg_external_debt_stock['PPG MLT external debt outstanding', time_period])) else 0), (input3_ppg_external_debt_stock['PPG ST external debt outstanding', time_period] if xl_bool(xl_isnumber(lambda: input3_ppg_external_debt_stock['PPG ST external debt outstanding', time_period])) else 0)), (input3_domestic_foreign_currency_stock['Outstanding of existing debt in foreign currency', time_period] if xl_bool(xl_isnumber(lambda: input3_domestic_foreign_currency_stock['Outstanding of existing debt in foreign currency', time_period])) else 0)), (input3_nonresident_foreign_currency_stock['Outstanding of existing debt in foreign currency', time_period] if xl_bool(xl_isnumber(lambda: input3_nonresident_foreign_currency_stock['Outstanding of existing debt in foreign currency', time_period])) else 0)))
        return as_measure((xl_add(xl_div((input3_nonresident_local_currency_stock[f'{indicator} of existing debt in local currency', time_period] if xl_bool(xl_isnumber(lambda: input3_nonresident_local_currency_stock[f'{indicator} of existing debt in local currency', time_period])) else 0), input3_input_3_macro_national_currency_per_u_s_dollar_e_o_p[time_period]), (input3_nonresident_foreign_currency_stock[f'{indicator} of existing debt in foreign currency', time_period] if xl_bool(xl_isnumber(lambda: input3_nonresident_foreign_currency_stock[f'{indicator} of existing debt in foreign currency', time_period])) else 0)) if xl_bool(xl_eq(external_domestic_debt_definition, lookup_afg)) else (input3_domestic_foreign_currency_stock[f'{indicator} of existing debt in foreign currency', time_period] if xl_bool(xl_isnumber(lambda: input3_domestic_foreign_currency_stock[f'{indicator} of existing debt in foreign currency', time_period])) else 0)))

    return data.INPUT3_LOCAL_CURRENCY_EXTERNAL_DEBT.collect(evaluate(formula, data.INPUT3_LOCAL_CURRENCY_EXTERNAL_DEBT.required.bind(TIME_PERIOD=input3_input_3_macro_current_account)), domain=data.INPUT3_LOCAL_CURRENCY_EXTERNAL_DEBT.required.bind(TIME_PERIOD=input3_input_3_macro_current_account))

