@publish(data.CUSTOM_PUB_AVG_REAL_INTEREST_RATE_BY_YEAR.schema, cells=data.CUSTOM_PUB_AVG_REAL_INTEREST_RATE_BY_YEAR.cells)
def custom_pub_avg_real_interest_rate_by_year(*, custom_pub_avg_real_interest_rate: float | str, input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute `custom_pub_avg_real_interest_rate_by_year` using authored coordinate identities."""
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if _p_time_period == 1:
            return as_measure(custom_pub_avg_real_interest_rate)
        return as_measure(custom_pub_avg_real_interest_rate_by_year[axis_step(_ax_time_period, time_period, -1)])

    custom_pub_avg_real_interest_rate_by_year = CoordinateReader('custom_pub_avg_real_interest_rate_by_year', data.CUSTOM_PUB_AVG_REAL_INTEREST_RATE_BY_YEAR.required.bind(TIME_PERIOD=input3_old_debt_service), formula)
    return data.CUSTOM_PUB_AVG_REAL_INTEREST_RATE_BY_YEAR.collect(((coord, custom_pub_avg_real_interest_rate_by_year[coord]) for coord in data.CUSTOM_PUB_AVG_REAL_INTEREST_RATE_BY_YEAR.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.CUSTOM_PUB_AVG_REAL_INTEREST_RATE_BY_YEAR.required.bind(TIME_PERIOD=input3_old_debt_service))

