@publish(data.REALISM1_PUBLIC_DEBT_CREATING_FLOWS.schema, cells=data.REALISM1_PUBLIC_DEBT_CREATING_FLOWS.cells)
def realism1_public_debt_creating_flows(*, realism1_public_current_vintage_projection: data.Series[float | str | None], input3_input_3_macro_current_account: data.Input3Input3MacroCurrentAccount) -> data.Realism1PublicDebtCreatingFlows:
    """Compute `realism1_public_debt_creating_flows` using authored coordinate identities."""
    data.INPUT3_INPUT_3_MACRO_CURRENT_ACCOUNT.schema.validate(input3_input_3_macro_current_account)
    _realism1_public_debt_creating_flows_table_0 = view(realism1_public_current_vintage_projection, rows=('of which: contribution from average real interest rate (in percent of GDP)',), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[8], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]))
    _realism1_public_debt_creating_flows_table_1 = view(realism1_public_current_vintage_projection, rows=('of which: contribution from average real interest rate (in percent of GDP)',), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[13], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[17]))
    _realism1_public_debt_creating_flows_table_2 = view(realism1_public_current_vintage_projection, rows=('of which: contribution from real GDP growth (in percent of GDP)',), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[8], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]))
    _realism1_public_debt_creating_flows_table_3 = view(realism1_public_current_vintage_projection, rows=('of which: contribution from real GDP growth (in percent of GDP)',), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[13], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[17]))
    _realism1_public_debt_creating_flows_table_4 = view(realism1_public_current_vintage_projection, rows=('Contribution from real exchange rate depreciation (in percent of GDP)',), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[8], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]))
    _realism1_public_debt_creating_flows_table_5 = view(realism1_public_current_vintage_projection, rows=('Contribution from real exchange rate depreciation (in percent of GDP)',), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[13], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[17]))
    _realism1_public_debt_creating_flows_table_6 = view(realism1_public_current_vintage_projection, rows=('Change in public sector debt (in percent of GDP)',), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[8], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]))
    _realism1_public_debt_creating_flows_table_7 = view(realism1_public_current_vintage_projection, rows=('Change in public sector debt (in percent of GDP)',), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[13], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[17]))
    _realism1_public_debt_creating_flows_table_8 = view(realism1_public_current_vintage_projection, rows=('Other identified debt-creating flows (in percent of GDP)',), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[8], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]))
    _realism1_public_debt_creating_flows_table_9 = view(realism1_public_current_vintage_projection, rows=('Other identified debt-creating flows (in percent of GDP)',), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[13], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[17]))
    def formula(indicator: str, variant: str) -> float | str | None:
        if indicator == 'Primary deficit' and variant == '5-year historical change':
            return as_measure(xl_sum(view(realism1_public_current_vintage_projection, rows=(f'{indicator} (in percent of GDP)',), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[8], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]))))
        elif indicator == 'Primary deficit' and variant == '5-year projected change':
            return as_measure(xl_sum(view(realism1_public_current_vintage_projection, rows=(f'{indicator} (in percent of GDP)',), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[13], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[17]))))
        elif indicator == 'Real interest rate' and variant == '5-year historical change':
            return as_measure(xl_sum(_realism1_public_debt_creating_flows_table_0))
        elif indicator == 'Real interest rate' and variant == '5-year projected change':
            return as_measure(xl_sum(_realism1_public_debt_creating_flows_table_1))
        elif indicator == 'Real GDP growth' and variant == '5-year historical change':
            return as_measure(xl_sum(_realism1_public_debt_creating_flows_table_2))
        elif indicator == 'Real GDP growth' and variant == '5-year projected change':
            return as_measure(xl_sum(_realism1_public_debt_creating_flows_table_3))
        elif indicator == 'Real Exchange rate depreciation' and variant == '5-year historical change':
            return as_measure(xl_sum(_realism1_public_debt_creating_flows_table_4))
        elif indicator == 'Real Exchange rate depreciation' and variant == '5-year projected change':
            return as_measure(xl_sum(_realism1_public_debt_creating_flows_table_5))
        elif indicator == 'Change in debt' and variant == '5-year historical change':
            return as_measure(xl_sum(_realism1_public_debt_creating_flows_table_6))
        elif indicator == 'Change in debt' and variant == '5-year projected change':
            return as_measure(xl_sum(_realism1_public_debt_creating_flows_table_7))
        elif indicator == 'Other debt creating flows' and variant == '5-year historical change':
            return as_measure(xl_sum(_realism1_public_debt_creating_flows_table_8))
        elif indicator == 'Other debt creating flows' and variant == '5-year projected change':
            return as_measure(xl_sum(_realism1_public_debt_creating_flows_table_9))
        elif indicator == 'Residual' and variant == '5-year historical change':
            return as_measure(xl_sum(view(realism1_public_current_vintage_projection, rows=(indicator,), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[8], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[12]))))
        return as_measure(xl_sum(view(realism1_public_current_vintage_projection, rows=(indicator,), cols=span(input3_input_3_macro_current_account.domain.axis('TIME_PERIOD'), input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[13], input3_input_3_macro_current_account.domain.axis('TIME_PERIOD').keys[17]))))

    return data.REALISM1_PUBLIC_DEBT_CREATING_FLOWS.collect(evaluate(formula, data.REALISM1_PUBLIC_DEBT_CREATING_FLOWS.required))

