@dataclass(frozen=True, slots=True)
class ScanPvBaseMultilateralsByYearResult:
    """Complete named results of one recurrence group evaluation."""
    pv_base_multilaterals_by_year: data.Series[int | str | None]
    pv_base_grace_ida_regular_by_year: data.Series[int | str | None]
    pv_base_output_projection_year: data.Series[int | str | None]

def scan_pv_base_multilaterals_by_year(*, macro_debt_data: int | str) -> ScanPvBaseMultilateralsByYearResult:
    """Evaluate the recurrence group `pv_base_multilaterals_by_year`, `pv_base_grace_ida_regular_by_year`, `pv_base_output_projection_year` and publish complete tensors."""
    def pv_base_multilaterals_by_year_formula(time_period: int) -> int | str | None:
        if time_period == 2024:
            return as_measure(macro_debt_data, 'int')
        return as_measure(pv_base_grace_ida_regular_by_year[time_period], 'int')

    pv_base_multilaterals_by_year = CoordinateReader('pv_base_multilaterals_by_year', data.PV_BASE_MULTILATERALS_BY_YEAR.required, pv_base_multilaterals_by_year_formula)
    def pv_base_grace_ida_regular_by_year_formula(time_period: int) -> int | str | None:
        return as_measure(pv_base_output_projection_year['IDA - regular', time_period], 'int')

    pv_base_grace_ida_regular_by_year = CoordinateReader('pv_base_grace_ida_regular_by_year', data.PV_BASE_GRACE_IDA_REGULAR_BY_YEAR.required, pv_base_grace_ida_regular_by_year_formula)
    def pv_base_output_projection_year_formula(instrument: str, time_period: int) -> int | str | None:
        if time_period == 2024:
            return as_measure(pv_base_multilaterals_by_year[2024], 'int')
        elif time_period == 2025:
            return as_measure(xl_add(pv_base_output_projection_year[instrument, time_period - 1], 1), 'int')
        return as_measure(xl_add(pv_base_output_projection_year['IDA - regular', time_period - 1], 1), 'int')

    pv_base_output_projection_year = CoordinateReader('pv_base_output_projection_year', data.PV_BASE_OUTPUT_PROJECTION_YEAR.required, pv_base_output_projection_year_formula)
    return ScanPvBaseMultilateralsByYearResult(
        pv_base_multilaterals_by_year=data.PV_BASE_MULTILATERALS_BY_YEAR.collect((coord, pv_base_multilaterals_by_year[coord]) for coord in data.PV_BASE_MULTILATERALS_BY_YEAR.required),
        pv_base_grace_ida_regular_by_year=data.PV_BASE_GRACE_IDA_REGULAR_BY_YEAR.collect((coord, pv_base_grace_ida_regular_by_year[coord]) for coord in data.PV_BASE_GRACE_IDA_REGULAR_BY_YEAR.required),
        pv_base_output_projection_year=data.PV_BASE_OUTPUT_PROJECTION_YEAR.collect((coord, pv_base_output_projection_year[coord]) for coord in data.PV_BASE_OUTPUT_PROJECTION_YEAR.required),
    )

