            return as_measure(xl_sub(pv_base_discount_debt_stock_fx[instrument, holder, axis_step(_ax_time_period, time_period, -1)], pv_base_discount_amortization_fx['Bonds (4 to 7 years)-FX', 'non-residents', time_period]))
