    return data.PV_STRESS_BOUNDS_TOTAL_DEBT_SERVICE_IN_USD.collect(evaluate(formula, data.PV_STRESS_BOUNDS_TOTAL_DEBT_SERVICE_IN_USD.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_STRESS_BOUNDS_TOTAL_DEBT_SERVICE_IN_USD.required.bind(TIME_PERIOD=input3_old_debt_service))

