@publish(data.PV_STRESS_TOTAL_DEBT_SERVICE.schema, cells=data.PV_STRESS_TOTAL_DEBT_SERVICE.cells)
def pv_stress_total_debt_service(*, pv_stress_interest: data.Series[float | str | None], pv_stress_amortization: data.Series[float | str | None], pv_stress_interest_scenario: data.Series[float | str | None], input3_old_debt_service: data.Input3OldDebtService) -> data.Series[float | str | None]:
    """Compute `pv_stress_total_debt_service` using authored coordinate identities."""
    data.PV_STRESS_INTEREST_SCENARIO.schema.bind(TIME_PERIOD=input3_old_debt_service).validate(pv_stress_interest_scenario)
    data.INPUT3_OLD_DEBT_SERVICE.schema.validate(input3_old_debt_service)
    def formula(scenario: str, time_period: int) -> float | str | None:
        _ax_time_period = input3_old_debt_service.domain.axis('TIME_PERIOD')
        _p_time_period = _ax_time_period.position(time_period)
        if scenario == 'Market financing stress test / primary' and _p_time_period == 0:
            return as_measure(xl_add(pv_stress_interest_scenario['Market financing stress test / primary', time_period], pv_stress_amortization['Market financing stress test / primary', time_period]))
        elif scenario == 'Market financing stress test / secondary' and _p_time_period == 0:
            return as_measure(xl_add(pv_stress_interest_scenario['Market financing stress test / secondary', time_period], pv_stress_amortization['Market financing stress test / secondary', time_period]))
        elif scenario == 'Key variables at historical average' and _p_time_period >= 1:
            return as_measure(xl_add(pv_stress_interest['Key variables at historical average', time_period], pv_stress_amortization['Key variables at historical average', time_period]))
        elif scenario == 'Tailored Stress Test 3. Commodity Price shock -External' and _p_time_period >= 1:
            return as_measure(xl_add(pv_stress_interest['Tailored Stress Test 3. Commodity Price shock -External', time_period], pv_stress_amortization['Tailored Stress Test 3. Commodity Price shock -External', time_period]))
        elif scenario == 'Market financing stress test / primary' and _p_time_period >= 1:
            return as_measure(xl_add(pv_stress_interest['Market financing stress test / primary', time_period], pv_stress_amortization['Market financing stress test / primary', time_period]))
        return as_measure(xl_add(pv_stress_interest['Market financing stress test / secondary', time_period], pv_stress_amortization['Market financing stress test / secondary', time_period]))

    return data.PV_STRESS_TOTAL_DEBT_SERVICE.collect(evaluate(formula, data.PV_STRESS_TOTAL_DEBT_SERVICE.required.bind(TIME_PERIOD=input3_old_debt_service)), domain=data.PV_STRESS_TOTAL_DEBT_SERVICE.required.bind(TIME_PERIOD=input3_old_debt_service))

